//! The functions of the game's that its data still names by address and that are not the
//! typed menus' (`menu::table_routes`): the threads' routines (the slots), items' actions
//! and screens the menus' memory holds, by their address (as an RVA), each run by its Rust
//! version. Kept by hand since 2026-10-24 (once generated by a removed
//! `tools/gen_routes.py`): only the addresses a pointer in the game's data
//! (`relocations::PLACES`) or a code constant of Rust's names; any other address called
//! ends the program, "not ported" (`menu::table_calls`).

use crate::errors::Refused;
use crate::framework::{IMAGE_BASE, Regs};

/// Runs the function at `at` (an RVA) with `r`, if it has a Rust version here.
#[rustfmt::skip]
pub fn by_rva(at: usize, r: &mut Regs) -> Option<Result<(), Refused>> {
    match at.wrapping_add(IMAGE_BASE) {
        0x4078DA => Some(crate::input::input_thread::thread_routine()), // input::input_thread
        0x407F95 => Some({ let key = crate::input::take_key::take_key(); r.eax = (r.eax & !0xFF) | u32::from(key); r.set_zero(key == 0); r.set_carry(false); Ok(()) }), // input::take_key
        0x409CCE => Some(unsafe { crate::audio::thread::audio_thread(&crate::audio::thread::ThreadVars::game()) }), // audio::thread
        0x40F7A4 => Some({ crate::sound::play_tune_9::play_tune_9(); Ok(()) }), // sound::play_tune_9
        0x40F826 => Some({ crate::sound::stop_music::stop_music(); Ok(()) }), // sound::stop_music
        0x410C17 => crate::threading::shutdown_thread::shutdown_thread(), // threading::shutdown_thread
        0x4183C3 => Some(crate::net::receive_thread::receive_thread()), // net::receive_thread
        0x4467C7 => Some(unsafe { crate::race::loading_bar_frame::loading_bar_frame() }), // race::loading_bar_frame
        0x469C40 => Some(unsafe { crate::screens::car_page_description::car_page_description(r.edi as *mut _) }.map(|too_wide| { r.set_carry(too_wide); r.set_zero(!too_wide) })), // screens::car_page_description
        0x469CA0 => Some(unsafe { crate::screens::car_page_dimensions::car_page_dimensions(r.edi as *mut _) }.map(|too_wide| { r.set_carry(too_wide); r.set_zero(!too_wide) })), // screens::car_page_dimensions
        0x469F12 => Some(unsafe { crate::screens::car_page_engine::car_page_engine(r.edi as *mut _) }.map(|too_wide| { r.set_carry(too_wide); r.set_zero(!too_wide) })), // screens::car_page_engine
        0x46A193 => Some(unsafe { crate::screens::car_page_transmission::car_page_transmission(r.edi as *mut _) }.map(|too_wide| { r.set_carry(too_wide); r.set_zero(!too_wide) })), // screens::car_page_transmission
        0x46B44F => Some(unsafe { crate::menu::controller_items::raise_controller_sensitivity(r.edi) }), // menu::raise_controller_sensitivity
        0x46E6E1 => Some(crate::saves::load_savegame::entry(r)), // saves::load_savegame
        0x46E899 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::load_championship_46e899_loop::SCREEN, r) }), // menu::load_championship_46e899_loop
        0x46EB7A => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::save_setup_loop::SCREEN, r) }), // menu::save_setup_loop
        0x46F7FD => Some({ unsafe { crate::scene::prepare_menu_scene::prepare_menu_scene() }.apply(r); Ok(()) }), // scene::prepare_menu_scene
        0x46FAEE => Some(unsafe { crate::menu::stage_view_steps::step_stage_page(false) }), // menu::previous_stage_page
        0x46FB27 => Some(unsafe { crate::menu::stage_view_steps::step_stage_page(true) }), // menu::next_stage_page
        0x4703C2 => Some(unsafe { crate::menu::apply_screen_mode::apply_screen_mode() }), // menu::apply_screen_mode
        0x470529 => Some(unsafe { crate::menu::replay_item_c::replay_item_c(&crate::menu::screen_loop::carried(r)) }), // menu::replay_item_c
        0x47052F => Some(unsafe { crate::menu::replay_item_b::replay_item_b(&crate::menu::screen_loop::carried(r)) }), // menu::replay_item_b
        0x47053E => Some(unsafe { crate::menu::replay_item_a::replay_item_a(&crate::menu::screen_loop::carried(r)) }), // menu::replay_item_a
        0x471C82 => Some({ crate::menu::go_back::go_back(); Ok(()) }), // menu::go_back
        0x473B21 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::next_stage_loop::SCREEN, r) }), // menu::next_stage_loop
        0x475C12 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::start_rally_loop::SCREEN, r) }), // menu::start_rally_loop
        0x475F1A => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::network_rally_loop::SCREEN, r) }), // menu::network_rally_loop
        0x4764DC => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::championship_new_simulation_loop::SCREEN, r) }), // menu::championship_new_simulation_loop
        0x4767E3 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::audio_setup_loop::SCREEN, r) }), // menu::audio_setup_loop
        0x477106 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::options_loop::SCREEN, r) }), // menu::options_loop
        0x4773D6 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::player_details_loop::SCREEN, r) }), // menu::player_details_loop
        0x477692 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::player1_details_loop::SCREEN, r) }), // menu::player1_details_loop
        0x477960 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::player2_details_loop::SCREEN, r) }), // menu::player2_details_loop
        0x477C10 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::player3_details_loop::SCREEN, r) }), // menu::player3_details_loop
        0x477E97 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::player4_details_loop::SCREEN, r) }), // menu::player4_details_loop
        0x47814C => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::player1_controller_loop::SCREEN, r) }), // menu::player1_controller_loop
        0x4783F6 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::player1_buttons_loop::SCREEN, r) }), // menu::player1_buttons_loop
        0x4786AA => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::player2_controller_loop::SCREEN, r) }), // menu::player2_controller_loop
        0x478954 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::player2_buttons_loop::SCREEN, r) }), // menu::player2_buttons_loop
        0x478C08 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::player3_controller_loop::SCREEN, r) }), // menu::player3_controller_loop
        0x478EB2 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::player3_buttons_loop::SCREEN, r) }), // menu::player3_buttons_loop
        0x479166 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::player4_controller_loop::SCREEN, r) }), // menu::player4_controller_loop
        0x479410 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::player4_buttons_loop::SCREEN, r) }), // menu::player4_buttons_loop
        0x4796C4 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::redefine_keys_player1_loop::SCREEN, r) }), // menu::redefine_keys_player1_loop
        0x47999E => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::redefine_keys_player2_loop::SCREEN, r) }), // menu::redefine_keys_player2_loop
        0x479C78 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::redefine_keys_player3_loop::SCREEN, r) }), // menu::redefine_keys_player3_loop
        0x479F52 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::redefine_keys_player4_loop::SCREEN, r) }), // menu::redefine_keys_player4_loop
        0x47A22C => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::visual_preferences_loop::SCREEN, r) }), // menu::visual_preferences_loop
        0x47A652 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::car_specification_loop::SCREEN, r) }), // menu::car_specification_loop
        0x47A973 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::slideshow_loop::SCREEN, r) }), // menu::slideshow_loop
        0x47D8F7 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::in_game_options_loop::SCREEN, r) }), // menu::in_game_options_loop
        0x47E826 => Some({ crate::menu::update_blink::update_blink(); Ok(()) }), // menu::update_blink
        0x47ED32 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::load_championship_loop::SCREEN, r) }), // menu::load_championship_loop
        0x47EFFF => Some(unsafe { crate::menu::load_background::load_background(r.eax as *mut u8, r.ebx, &mut crate::text::draw_text::GameCanvas) }.map(|()| r.set_carry(false))), // menu::load_background
        0x47F034 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::save_championship_loop::SCREEN, r) }), // menu::save_championship_loop
        0x480592 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::visual_options_loop::SCREEN, r) }), // menu::visual_options_loop
        0x480821 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::advanced_audio_loop::SCREEN, r) }), // menu::advanced_audio_loop
        0x481771 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::simple_select_players_loop::SCREEN, r) }), // menu::simple_select_players_loop
        0x482382 => Some(unsafe { crate::menu::single_rally::single_rally(&crate::menu::screen_loop::carried(r)) }), // menu::single_rally
        0x487999 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::arcade_select_level_loop::SCREEN, r) }), // menu::arcade_select_level_loop
        0x487CC9 => Some(unsafe { crate::menu::arcade_level_1::arcade_level_1(&crate::menu::screen_loop::carried(r)) }), // menu::arcade_level_1
        0x487D10 => Some(unsafe { crate::menu::arcade_level_2::arcade_level_2(&crate::menu::screen_loop::carried(r)) }), // menu::arcade_level_2
        0x487D57 => Some(unsafe { crate::menu::arcade_level_3::arcade_level_3(&crate::menu::screen_loop::carried(r)) }), // menu::arcade_level_3
        0x487D9E => Some(unsafe { crate::menu::arcade_level_4::arcade_level_4(&crate::menu::screen_loop::carried(r)) }), // menu::arcade_level_4
        0x487DE5 => Some(unsafe { crate::menu::arcade_level_5::arcade_level_5(&crate::menu::screen_loop::carried(r)) }), // menu::arcade_level_5
        0x48BCDC => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::time_trial_select_players_loop::SCREEN, r) }), // menu::time_trial_select_players_loop
        0x48E169 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::information_loop::SCREEN, r) }), // menu::information_loop
        0x48E494 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::view_best_times_loop::SCREEN, r) }), // menu::view_best_times_loop
        0x48EC30 => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::view_courses_loop::SCREEN, r) }), // menu::view_courses_loop
        0x48EF2E => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::view_best_scores_loop::SCREEN, r) }), // menu::view_best_scores_loop
        0x4A94EC => Some(unsafe { crate::menu::rally_results::rally_results(&crate::menu::screen_loop::carried(r)) }), // menu::rally_results
        0x4A9583 => Some(unsafe { crate::menu::championship_standings::championship_standings(&crate::menu::screen_loop::carried(r)) }), // menu::championship_standings
        0x4A99AA => Some(unsafe { crate::menu::screen_loop::run_screen_regs(&crate::menu::new_simulation_loop::SCREEN, r) }), // menu::new_simulation_loop
        _ => None,
    }
}
